import React from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import './../assets/css/admin-dashboard.css'; // We'll create this file next

const AdminDashboard = () => {
  return (
    <div className="admin-container">
      <aside className="sidebar">
        <h2 className="logo">Admin Dashboard</h2>
        <nav className="main-nav">
          <NavLink to="/admin-dashboard/students" activeClassName="active-link" className="nav-item">Student Management</NavLink>
          <NavLink to="/admin-dashboard/teachers" activeClassName="active-link" className="nav-item">Teacher Management</NavLink>
          <NavLink to="/admin-dashboard/fees" activeClassName="active-link" className="nav-item">Fee Management</NavLink>
        </nav>
      </aside>

      <main className="content">
        <Outlet />
      </main>
    </div>
  );
};

export default AdminDashboard;
